package com.example.lms.config;
import com.example.lms.content.*; import com.example.lms.quiz.*; import com.example.lms.user.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration;
@Configuration public class DemoData {
 @Bean CommandLineRunner seed(UserRepository users, ContentRepository contents, QuizRepository quizzes) { return args -> { User teacher=users.findByUsername("asha").orElseGet(()->users.findByEmail("asha@lms.local").map(u->{u.setCredentials("asha","teacher123");return users.save(u);}).orElseGet(()->users.save(new User("Asha Teacher","asha@lms.local","asha","teacher123",Role.TEACHER)))); User admin=users.findByUsername("admin").orElseGet(()->users.findByEmail("admin@lms.local").map(u->{u.setCredentials("admin","qwertyuiop");return users.save(u);}).orElseGet(()->users.save(new User("Platform Admin","admin@lms.local","admin","qwertyuiop",Role.ADMIN)))); if(contents.count()==0){contents.save(new Content("Welcome to the LMS","Start your learning journey with our latest courses and announcements.",ContentType.POST,teacher,true)); Content quiz=new Content("Java Fundamentals Quiz","Test your understanding of Java 17 fundamentals.",ContentType.QUIZ,teacher,true); quiz.setQuizDetails(1,30); contents.save(quiz); Content guide=new Content("Spring Boot 3.5 Study Guide","This document explains the core concepts covered in the module.",ContentType.DOCUMENT,teacher,true); guide.setFileName("spring-boot-study-guide.pdf"); contents.save(guide); Content image=new Content("Learning roadmap","A visual roadmap for the semester.",ContentType.IMAGE,admin,true); image.setMediaUrl("/images/learning-roadmap.svg"); contents.save(image);} contents.findByPublishedTrueOrderByUploadedAtDesc().stream().filter(c->c.getType()==ContentType.QUIZ).forEach(c-> {if(quizzes.findByContentId(c.getId()).isEmpty()){Quiz q=new Quiz(c,c.getQuizDurationMinutes()==null?30:c.getQuizDurationMinutes());q.add(new QuizQuestion("Which Java version is used by this platform?","Java 8","Java 11","Java 17","Java 21",2,"The platform is built with Java 17."));quizzes.save(q);}}); }; }
}

